  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) { flush(); out.push({ op: ' ', text: a[i] }); i++; j++; }
    else if (j >= m || (i < n && dp[i + 1][j] >= dp[i][j + 1])) { dels.push(a[i++]); }
    else { adds.push(b[j++]); }
  }
  flush();
  return out;
}

